java.awt.image.BufferedImage testImage = new java.awt.image.BufferedImage(100, 50, java.awt.image.BufferedImage.TYPE_INT_ARGB);
net.coobird.thumbnailator.util.exif.Orientation orientation = net.coobird.thumbnailator.util.exif.Orientation.typeOf(6);
net.coobird.thumbnailator.filters.ImageFilter filter = net.coobird.thumbnailator.util.exif.ExifFilterUtils.getFilterForOrientation(orientation);

java.awt.image.BufferedImage result = net.coobird.thumbnailator.Thumbnails.of(testImage)
    .addFilter(filter)
    .scale(1.0)
    .asBufferedImage();

assert result.getWidth() == 50 : "Expected width 50, got " + result.getWidth();
assert result.getHeight() == 100 : "Expected height 100, got " + result.getHeight();

System.out.println("__CHECK__ getFilterForOrientation " + result.getWidth() + "x" + result.getHeight());

